type MemoryStarLogoProps = {
  tone?: "black" | "white";
};

export function MemoryStarLogo({ tone = "black" }: MemoryStarLogoProps) {
  const [isHover, setIsHover] = useState(false);
  const baseColor = tone === "white" ? "#FFFFFF" : "#000000";
  const accentColor = tone === "white" ? "#FFFFFF" : "#000000";

  return (
    <span
      className="inline-flex"
      onMouseEnter={() => setIsHover(true)}
      onMouseLeave={() => setIsHover(false)}
      onFocus={() => setIsHover(true)}
      onBlur={() => setIsHover(false)}
      role="img"
      aria-label="memoryos"
    >
      <motion.svg
        width="207"
        height="29"
        viewBox="0 0 207 29"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className="h-[29px] w-[207px]"
      >
        <path d={WORD_PATH} fill={baseColor} />
        <path d={TM_PATH} fill={baseColor} />

        <motion.path
          d={STAR_PATH}
          fill={baseColor}
          animate={
            isHover
              ? {
                  fill: "#FFFFFF",
                  filter: [
                    "drop-shadow(0 0 0px rgba(255,255,255,0))",
                    "drop-shadow(0 0 8px rgba(255,255,255,1))",
                    "drop-shadow(0 0 3px rgba(255,255,255,0.85))",
                  ],
                }
              : {
                  fill: baseColor,
                  filter: "drop-shadow(0 0 0px rgba(255,255,255,0))",
                }
          }
          transition={
            isHover
              ? {
                  fill: { duration: 0.22, delay: 0.44, ease: "easeOut" },
                  filter: {
                    duration: 1.1,
                    delay: 0.58,
                    repeat: Number.POSITIVE_INFINITY,
                    ease: "easeInOut",
                  },
                }
              : {
                  fill: { duration: 0.12 },
                  filter: { duration: 0.12 },
                }
          }
        />

        <motion.path
          d={STAR_PATH}
          fill="none"
          stroke={accentColor}
          strokeWidth="1.6"
          strokeLinecap="round"
          initial={{ opacity: 0, pathLength: 0 }}
          animate={
            isHover
              ? {
                  opacity: 1,
                  pathLength: 1,
                }
              : {
                  opacity: 0,
                  pathLength: 0,
                }
          }
          transition={
            isHover
              ? {
                  pathLength: { duration: 0.42, ease: "easeOut" },
                  opacity: { duration: 0.12 },
                }
              : {
                  pathLength: { duration: 0.16, ease: "easeIn" },
                  opacity: { duration: 0.1 },
                }
          }
        />

        <motion.path
          d={STAR_PATH}
          fill="none"
          stroke="#FFFFFF"
          strokeWidth="1.6"
          strokeDasharray="0.1 0.9"
          pathLength={1}
          initial={{ opacity: 0, pathOffset: 1 }}
          animate={
            isHover
              ? {
                  opacity: [0, 1, 0.2, 0],
                  pathOffset: [1, 0.2, -0.5, -1],
                }
              : {
                  opacity: 0,
                  pathOffset: 1,
                }
          }
          transition={
            isHover
              ? {
                  opacity: {
                    duration: 0.95,
                    delay: 0.6,
                    repeat: Number.POSITIVE_INFINITY,
                    ease: "easeInOut",
                  },
                  pathOffset: {
                    duration: 0.95,
                    delay: 0.6,
                    repeat: Number.POSITIVE_INFINITY,
                    ease: "linear",
                  },
                }
              : {
                  opacity: { duration: 0.08 },
                  pathOffset: { duration: 0.08 },
                }
          }
        />
      </motion.svg>
    </span>
  );
}
